/// A single phase wake reads only its tab's Claude record. The same two
/// workers remain the negative controls for generic and coalesced wakes:
/// both records are read, including one whose stamp did not move.
#[test]
fn phase_follow_reads_only_the_changed_workers_record() {
    let world = Arc::new(World::default());
    let mut hooks = hooks(&world, parking_body(&world));
    let reads = Arc::new(Mutex::new(Vec::<String>::new()));
    let counted = Arc::clone(&reads);
    hooks.acts.follow = Arc::new(move |sid, _| {
        counted.lock().unwrap().push(sid.to_string());
        Foreground::Agent
    });
    let following: Vec<_> = ["a", "b"]
        .into_iter()
        .map(|sid| {
            (
                sid.to_string(),
                Arc::new(Mutex::new(Kept {
                    snapshot: Some(snap(sid)),
                    ..Kept::default()
                })),
            )
        })
        .collect();
    let stamp = FollowStamp {
        group: 12,
        reader: Some(Program::Claude),
        rev: 1,
        ..FollowStamp::default()
    };
    let mut stamps = HashMap::from([("a".to_string(), stamp), ("b".to_string(), stamp)]);
    let mut followed = HashMap::new();
    // One instant for every look: no settle a move arms comes due here.
    let (mut settle, now) = (HashMap::new(), Instant::now());
    follow_entries(
        &following,
        &stamps,
        (&mut followed, &mut settle),
        true,
        now,
        &hooks,
    );
    assert_eq!(*reads.lock().unwrap(), ["a", "b"]);

    reads.lock().unwrap().clear();
    stamps.get_mut("a").unwrap().rev += 1;
    let phase_only = full_follow_due(false, 8, 8, 4, 5);
    assert!(!phase_only, "one phase wake");
    follow_entries(
        &following,
        &stamps,
        (&mut followed, &mut settle),
        phase_only,
        now,
        &hooks,
    );
    assert_eq!(*reads.lock().unwrap(), ["a"]);

    reads.lock().unwrap().clear();
    let generic_and_phase = full_follow_due(false, 8, 9, 4, 5);
    assert!(generic_and_phase);
    follow_entries(
        &following,
        &stamps,
        (&mut followed, &mut settle),
        generic_and_phase,
        now,
        &hooks,
    );
    assert_eq!(*reads.lock().unwrap(), ["a", "b"]);

    reads.lock().unwrap().clear();
    let coalesced = full_follow_due(false, 8, 8, 4, 6);
    assert!(coalesced);
    follow_entries(
        &following,
        &stamps,
        (&mut followed, &mut settle),
        coalesced,
        now,
        &hooks,
    );
    assert_eq!(*reads.lock().unwrap(), ["a", "b"]);

    reads.lock().unwrap().clear();
    stamps.remove("b");
    follow_entries(
        &following,
        &stamps,
        (&mut followed, &mut settle),
        false,
        now,
        &hooks,
    );
    assert_eq!(*reads.lock().unwrap(), ["b"], "unknown stamp falls back");
    assert!(full_follow_due(false, 8, 8, u64::MAX, 0), "wrap");
    assert!(full_follow_due(true, 8, 8, 4, 4), "timer");
}

/// The host's own acts are gated by the window's parsed `[harness]`
/// table — the master switch and each act's key — not by a second reader
/// of the file, and live: neither key restarts a worker ([`effective`]
/// masks both). NEGATIVE CONTROL: each key limits only its own act, and
/// `[harness] usage_credits` neither.
#[test]
fn the_host_switches_are_the_parsed_table() {
    let read = |cfg: &SupervisorConfig| {
        let s = Switches::default();
        s.set(cfg, false);
        (s.upgrade(), s.relaunch())
    };
    let mut credits = on();
    credits.set("usage_credits", "true").unwrap();
    assert_eq!(read(&credits), (true, true));
    assert_eq!(read(&on()), (true, true));
    assert_eq!(read(&off()), (false, false));
    let mut no_upgrade = on();
    no_upgrade.set("upgrade", "false").unwrap();
    assert_eq!(read(&no_upgrade), (false, true));
    let mut no_relaunch = on();
    no_relaunch.set("relaunch", "false").unwrap();
    assert_eq!(read(&no_relaunch), (true, false));
    assert_eq!(effective(&no_upgrade), on());
    assert_eq!(effective(&no_relaunch), on());
}

/// The live E2E's D5: the hosted loop kept no journal, so its SKIPPED,
/// WAITING and ESCALATED lines — a refused attention, a guard that never
/// matched — were visible nowhere. Every worker now journals beside its
/// session's ledger, and snapshots a tasked session's result where its
/// record may name one (`<state>/tasks/`, the task record's own directory).
/// NEGATIVE CONTROL: with no state root, neither (and the policy rides
/// unchanged either way).
#[test]
fn every_worker_journals_beside_its_ledger() {
    let dir = std::env::temp_dir().join(format!("aterm-hh-journal-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    let cfg = SupervisorConfig::default();
    let opts = hosted_opts(&cfg, "s-0123", Some(&dir));
    assert_eq!(
        opts.journal.as_deref(),
        Some(dir.join("drive").join("s-0123.journal.jsonl").as_path())
    );
    assert_eq!(opts.tasks.as_deref(), Some(dir.join("tasks").as_path()));
    assert_eq!(opts.policy, cfg);
    assert_eq!(hosted_opts(&cfg, "s-0123", None).journal, None);
    assert_eq!(hosted_opts(&cfg, "s-0123", None).tasks, None);
    let _ = std::fs::remove_dir_all(&dir);
}

/// The laws review of 2026-09-24: the host keyed its roster on the argv0
/// word (`claude`|`codex`) while the server identified a Claude Code
/// started as `node` by its frame — the rows were raised and nothing was
/// supervised. The roster now reads aterm-phase's one name table, then
/// the reader the server's verdict used. NEGATIVE CONTROLS: a shell with
/// no identified reader, and a runtime whose screen read as no agent,
/// are not supervised; a name wins over a stale reader, and a reader left
/// under a shell's name (a same-group exec, read before the next verdict)
/// names no agent, as the verdict identifies by the screen only under a
/// runtime or no name yet.
#[test]
fn the_roster_takes_an_agent_identified_by_name_or_by_its_screen() {
    use crate::session_timeline::AgentPublication;
    use aterm_phase::Program;
    let publication = |program: Option<&str>, reader: Option<Program>| AgentPublication {
        program: program.map(str::to_string),
        reader,
        ..AgentPublication::default()
    };
    assert_eq!(
        agent_of(&publication(Some("claude"), None)),
        Some(Program::Claude)
    );
    assert_eq!(
        agent_of(&publication(Some("claude-code"), None)),
        Some(Program::Claude)
    );
    assert_eq!(
        agent_of(&publication(Some("codex"), None)),
        Some(Program::Codex)
    );
    assert_eq!(
        agent_of(&publication(Some("node"), Some(Program::Claude))),
        Some(Program::Claude),
        "a Claude Code started as node, identified by its frame"
    );
    assert_eq!(agent_of(&publication(Some("zsh"), None)), None);
    assert_eq!(agent_of(&publication(Some("node"), None)), None);
    assert_eq!(
        agent_of(&publication(Some("node"), Some(Program::Generic))),
        None
    );
    assert_eq!(
        agent_of(&publication(Some("codex"), Some(Program::Claude))),
        Some(Program::Codex)
    );
    assert_eq!(
        agent_of(&publication(None, Some(Program::Claude))),
        Some(Program::Claude),
        "identified by its frame before its name resolved"
    );
    assert_eq!(
        agent_of(&publication(Some("zsh"), Some(Program::Claude))),
        None,
        "a reader the shell's name left behind"
    );
}

/// GEMINI CLI RUNS AS `node` (its name never reaches `program=`): the
/// verdict's screen sniff names it on every screen it draws, its prompt is
/// its own ([`identified_agent`]: the frozen-tab count and the integration
/// heal keep its prompts), and a worker is admitted for it under that name
/// ([`agent_of`]: the reader under a runtime's name), as Muse Code's reader
/// under `node` is. NEGATIVE CONTROLS: its reader left under a shell's name
/// owns nothing and is admitted nothing, and the generic reader under `node`
/// (a screen no agent's grammar names) owns nothing and is admitted nothing.
#[test]
fn a_node_hosted_gemini_cli_owns_its_prompt_and_is_supervised() {
    use crate::session_timeline::AgentPublication;
    use aterm_phase::Program;
    let rows = aterm_phase::prompt::fixtures::screen(aterm_phase::gemini::fixtures::IDLE);
    let read = aterm_phase::identify(Some("node"), &rows).program();
    assert_eq!(read, Program::Gemini, "the measured composer under node");
    let publication = |program: &str, reader: Program| AgentPublication {
        program: Some(program.to_string()),
        reader: Some(reader),
        ..AgentPublication::default()
    };
    assert_eq!(
        identified_agent(&publication("node", read)),
        Some(Program::Gemini)
    );
    assert_eq!(agent_of(&publication("node", read)), Some(Program::Gemini));
    assert_eq!(identified_agent(&publication("zsh", read)), None);
    assert_eq!(agent_of(&publication("zsh", read)), None, "a shell's name");
    assert_eq!(
        identified_agent(&publication("node", Program::Muse)),
        Some(Program::Muse)
    );
    assert_eq!(
        agent_of(&publication("node", Program::Muse)),
        Some(Program::Muse),
        "Muse Code is supervised too"
    );
    assert_eq!(
        identified_agent(&publication("node", Program::Generic)),
        None
    );
    assert_eq!(
        agent_of(&publication("node", Program::Generic)),
        None,
        "no agent's screen"
    );
}

/// One usage tap reading handed to the session log: `(sid, h5, d7)`.
type UsageLogged = (String, Option<u32>, Option<u32>);

/// A fake roster the test moves, plus the calls the seams saw.
#[derive(Default)]
struct World {
    roster: Mutex<Vec<(String, Program)>>,
    /// The usage tap readings handed to the session log ([`Hooks::log_usage`]).
    usage: Mutex<Vec<UsageLogged>>,
    /// The sessions' own Autopilot words ([`Hooks::autopilot`]).
    words: Mutex<HashMap<String, Autopilot>>,
    /// The host's reads of those words: one a pass while it supervises.
    word_reads: AtomicUsize,
    runs: AtomicUsize,
    badges: Mutex<Vec<(String, Option<String>)>>,
    /// What the workers told the window about themselves ([`HostNote`]).
    notes: Mutex<Vec<HostNote>>,
    /// The loop's next tries as its workers told them, in order
    /// ([`Hooks::waiting`]): `(sid, plan)`, `None` for a plan cleared.
    told: Mutex<Vec<(String, Option<crate::presence::RetryPlan>)>>,
    /// This world's own claim epoch: the process-wide one moves with
    /// every other test's claim release.
    released: AtomicU64,
}

impl World {
    fn set(&self, roster: &[(&str, Program)]) {
        *self.roster.lock().unwrap() = roster.iter().map(|(s, a)| ((*s).to_string(), *a)).collect();
        ring();
    }

    /// Session `sid`'s own Autopilot word is `word` (`None`: unset), and the
    /// host is rung, as a `meta set|unset autopilot` rings it.
    fn word(&self, sid: &str, word: Option<Autopilot>) {
        let mut words = self.words.lock().unwrap();
        match word {
            Some(word) => words.insert(sid.to_string(), word),
            None => words.remove(sid),
        };
        drop(words);
        ring();
    }

    /// Wait until the host has made two whole passes (two reads of the
    /// words) since now — one begun after any change made before this call
    /// — so what a pass would do has been done. A hang detector.
    fn passes(&self) {
        let seen = self.word_reads.load(Ordering::SeqCst);
        ring();
        until("two passes", || {
            let now = self.word_reads.load(Ordering::SeqCst);
            if now < seen + 2 {
                ring();
            }
            now >= seen + 2
        });
    }
}

/// A body that parks until it is stopped — through the interrupter it
/// publishes, the path a real stop takes.
fn parking_body(world: &Arc<World>) -> Arc<BodyFn> {
    let world = Arc::clone(world);
    Arc::new(move |job: &WorkerJob| {
        world.runs.fetch_add(1, Ordering::SeqCst);
        let me = std::thread::current();
        *job.interrupt.lock().unwrap() = Some(Box::new(move || me.unpark()));
        while !job.stop.load(Ordering::SeqCst) {
            std::thread::park();
        }
        BodyEnd::Stopped
    })
}

fn hooks(world: &Arc<World>, body: Arc<BodyFn>) -> Hooks {
    let w8 = Arc::clone(world);
    let (w1, w2, w3, w4, w5, w6, w7) = (
        Arc::clone(world),
        Arc::clone(world),
        Arc::clone(world),
        Arc::clone(world),
        Arc::clone(world),
        Arc::clone(world),
        Arc::clone(world),
    );
    Hooks {
        roster: Arc::new(move || {
            w1.roster
                .lock()
                .unwrap()
                .iter()
                .map(|(sid, program)| (sid.clone(), *program, FollowStamp::default()))
                .collect()
        }),
        autopilot: Arc::new(move || {
            w7.word_reads.fetch_add(1, Ordering::SeqCst);
            w7.words.lock().unwrap().clone()
        }),
        still_wanted: Arc::new(move |sid, _| {
            w2.roster
                .lock()
                .unwrap()
                .iter()
                .any(|(s, a)| s == sid && *a == Program::Claude)
        }),
        body,
        badge: Arc::new(move |sid, text| {
            w3.badges
                .lock()
                .unwrap()
                .push((sid.to_string(), text.map(str::to_string)));
        }),
        waiting: Arc::new(move |sid, plan| {
            w5.told.lock().unwrap().push((sid.to_string(), plan));
        }),
        fact: Arc::new(|_, _| {}),
        needs: Arc::new(|_, _, _| false),
        hold: Arc::new(|_, _| false),
        claim_epoch: Arc::new(move || w4.released.load(Ordering::SeqCst)),
        acts: Acts::inert(),
        backoff: Arc::new(quick_backoff),
        pause: Arc::new(quick_pause),
        carry_clock: Arc::new(MonotonicClock),
        upgrade_view: Arc::new(|_, _, _, _| ViewNext::default()),
        disk: Arc::new(|_| {}),
        codex_roster: Arc::new(Vec::new),
        note: Arc::new(move |note| w6.notes.lock().unwrap().push(note)),
        log_usage: Arc::new(move |sid, h5, d7| {
            w8.usage.lock().unwrap().push((sid.to_string(), h5, d7));
        }),
    }
}

/// The restart schedule the tests run under: [`restart_backoff`]'s shape
/// — growing, capped at the fifth — in tens of milliseconds, so a
/// session's whole budget is spent within a test.
fn quick_backoff(n: usize) -> Duration {
    const STEPS: [u64; 5] = [10, 20, 30, 40, 50];
    Duration::from_millis(STEPS[n.saturating_sub(1).min(STEPS.len() - 1)])
}

/// The upgrade's and the relaunch's pauses as the tests wait them: the timing
/// value's test values, a thousandth of each (the 10 s relaunch back-off,
/// 10 ms).
fn quick_pause(pause: Duration) -> Duration {
    aterm_gui_timing::Timing::FAST.of(pause)
}

/// The pause seam for a test whose successor must CARRY a restart through
/// more than one step ([`carry_in_flight_after_handoff`]). The carry's
/// bound ([`carry_bound`]: the record's stale horizon and two of the
/// longest pauses) goes through the same seam, so [`quick_pause`] makes it
/// 0.36 s — on the real clock a stall of either thread at load 125-140 ended
/// the carry before `a_restart_the_successor_cannot_carry_in_time_is_said`'s
/// park, 2 of 9 runs alone (2026-09-30), which now runs on a [`StepClock`].
/// A hundredth keeps every retry pause under a third of a second and the
/// bound at 3.6 s.
fn carry_pause(pause: Duration) -> Duration {
    pause / 100
}

/// A [`CarryClock`] that moves only as the carry waits: each wait adds its
/// length and returns at once. The carry's bound runs out on its own steps
/// and pauses — the same arithmetic, in no time at all — and never on a stall
/// of a loaded machine, which the real clock's tests buy off with a 3.6 s
/// bound ([`carry_pause`]) held under the inbox's lane.
struct StepClock {
    origin: Instant,
    /// Nanoseconds the carry has waited.
    waited: AtomicU64,
}

impl StepClock {
    fn new() -> Arc<Self> {
        Arc::new(Self {
            origin: Instant::now(),
            waited: AtomicU64::new(0),
        })
    }
}

impl CarryClock for StepClock {
    fn now(&self) -> Instant {
        self.origin + Duration::from_nanos(self.waited.load(Ordering::SeqCst))
    }

    fn sleep(&self, wait: Duration) {
        let nanos = u64::try_from(wait.as_nanos()).unwrap_or(u64::MAX);
        self.waited.fetch_add(nanos, Ordering::SeqCst);
    }
}

/// Waits for something that must happen. The minute is a hang detector,
/// not a latency budget: these waits pass in well under a second alone.
/// (The "not within … s: the successor runs" failures of
/// `the_real_host_conforms_to_the_worker_lifecycle_model` under parallel
/// runs were no slow host: its projection took a held worker for the
/// successor a release had started, so the wait counted one worker short
/// and never ended — round 32, fixed in `Probe::project`.)
fn until(what: &str, pred: impl Fn() -> bool) {
    let seen = aterm_spec::wait::within(
        aterm_spec::wait::MUST_HAPPEN,
        Duration::from_millis(5),
        || pred().then_some(()),
    );
    assert!(seen.is_some(), "not within 60 s: {what}");
}

fn on() -> SupervisorConfig {
    SupervisorConfig::default()
}

/// [`on`] under the ask-and-drain flow (`[harness] upgrade_ask = true`).
fn asking() -> SupervisorConfig {
    let mut c = SupervisorConfig::default();
    c.set("upgrade_ask", "true").unwrap();
    c
}

fn off() -> SupervisorConfig {
    let mut c = SupervisorConfig::default();
    c.set("enabled", "false").unwrap();
    c
}

/// The host's switches as `cfg` sets them.
fn switched(cfg: &SupervisorConfig) -> Arc<Switches> {
    let switches = Arc::new(Switches::default());
    switches.set(cfg, false);
    switches
}

/// The job of tab `sid`'s worker under `cfg` once its `agent` has left:
/// stopped, its exit handed, nothing kept yet.
fn left_job(sid: &str, agent: Program, cfg: &SupervisorConfig) -> WorkerJob {
    WorkerJob {
        sid: sid.to_string(),
        agent,
        opts: SuperviseOpts::hosted(),
        stop: Arc::new(AtomicBool::new(true)),
        revoked: Arc::default(),
        interrupt: Arc::default(),
        handover: Arc::default(),
        clear_badge: false,
        unset_mark: false,
        faults: Arc::default(),
        park: Arc::default(),
        look_at: Arc::default(),
        left: Arc::new(ExitWord::handed()),
        acting: Arc::default(),
        switches: switched(cfg),
        kept: Arc::default(),
        note: Arc::default(),
        group: Arc::default(),
        host: std::sync::Weak::new(),
        watch_until: None,
        left_at_commit: Arc::default(),
        beside: Arc::default(),
    }
}

/// Tab `sid`'s worker's idle host over `hooks`, everything else fresh.
fn idle_host(sid: &str, agent: Program, switches: Arc<Switches>, hooks: Hooks) -> WorkerIdle {
    WorkerIdle {
        tap: Mutex::default(),
        login_latches: Arc::default(),
        lifted_off: false,
        beside: Arc::default(),
        sid: sid.to_string(),
        agent,
        stop: Arc::default(),
        grace: 0,
        park: Arc::default(),
        look_at: Arc::default(),
        acting: Arc::default(),
        stepped: Arc::default(),
        switches,
        kept: Arc::default(),
        hooks,
        run: Mutex::default(),
        activations: Arc::default(),
        owns: AtomicBool::new(false),
        background_at: Mutex::default(),
        tasked: Mutex::default(),
        finished: Mutex::default(),
        note: Arc::default(),
        clock_hold: Mutex::default(),
        net: NetProbe::new(),
        route: Mutex::default(),
        memory: Mutex::default(),
        points: Arc::default(),
        settle_later: AtomicBool::default(),
        told: AtomicU8::new(0),
    }
}

/// THE RESTORED TABS' AGENTS (2026-09-27): each `(tab, snapshot)` a cold
/// restore of the live layout hands the host is relaunched there by the
/// host's own act, off the caller's thread, once for a relaunch that
/// lands. NEGATIVE CONTROLS: `[harness] relaunch = false` relaunches
/// nothing, and neither does a headless instance.
#[test]
fn a_restored_tabs_agent_is_relaunched_while_relaunch_is_on() {
    let _lane = crate::message_inbox::own_lane_for_test();
    let run = |cfg: SupervisorConfig, headless: bool| {
        let world = Arc::new(World::default());
        let seen: Arc<Mutex<Vec<String>>> = Arc::default();
        let mut h = hooks(&world, parking_body(&world));
        let s = Arc::clone(&seen);
        h.acts.relaunch_restored = Arc::new(move |sid, snap, _, _| {
            assert_eq!(snap.tab, sid);
            s.lock().unwrap().push(sid.to_string());
            "adopted".to_string()
        });
        let host = HostHandle::start(cfg, headless, false, h);
        host.relaunch_restored(vec![
            restored("s-a", "in tab 1"),
            restored("s-b", "in tab 1"),
        ]);
        (host, seen)
    };
    let (host, seen) = run(on(), false);
    assert!(
        host.relaunches_restored(),
        "the reopened row reads the same gate"
    );
    until("both relaunched", || seen.lock().unwrap().len() == 2);
    assert_eq!(*seen.lock().unwrap(), ["s-a", "s-b"]);

    let mut limited = on();
    limited.set("relaunch", "false").unwrap();
    let (host, _) = run(limited, false);
    assert!(!host.relaunches_restored(), "relaunch = false");
    let (host, _) = run(on(), true);
    assert!(!host.relaunches_restored(), "headless");
    let (host, _) = run(off(), false);
    assert!(!host.relaunches_restored(), "[harness] off");
}

/// A tab whose relaunched agent still has not registered its conversation
/// cannot consume its retry pause before another tab's first relaunch.
/// Its own in-flight step is still retried later; neither is typed twice
/// after it succeeds.
#[test]
fn a_waiting_restored_tab_does_not_delay_another_tabs_first_step() {
    let _lane = crate::message_inbox::own_lane_for_test();
    let world = Arc::new(World::default());
    let seen: Arc<Mutex<Vec<String>>> = Arc::default();
    let first = Arc::new(AtomicUsize::new(0));
    let mut h = hooks(&world, parking_body(&world));
    let (calls, tries) = (Arc::clone(&seen), Arc::clone(&first));
    h.acts.relaunch_restored = Arc::new(move |sid, _, _, _| {
        calls.lock().unwrap().push(sid.to_string());
        if sid == "s-a" && tries.fetch_add(1, Ordering::SeqCst) == 0 {
            std::thread::sleep(Duration::from_millis(50));
            "wait:resume"
        } else {
            "adopted"
        }
        .to_string()
    });
    let host = HostHandle::start(on(), false, false, h);
    host.relaunch_restored(vec![
        restored("s-a", "in tab 1"),
        restored("s-b", "in tab 1"),
    ]);
    until("both first steps", || seen.lock().unwrap().len() >= 2);
    assert_eq!(seen.lock().unwrap()[..2], ["s-a", "s-b"]);
    until("the waiting tab retried", || {
        seen.lock().unwrap().len() == 3
    });
    assert_eq!(*seen.lock().unwrap(), ["s-a", "s-b", "s-a"]);

    // Tier-1: map the real worker's call order onto the model's actions.
    // The former nested loop enables RetryA immediately after FirstA;
    // this worker chose FirstB instead.
    let model = aterm_models_harness::harness_restored_first_attempt_model();
    let mut state = model.init_state();
    let mut first_a = false;
    for sid in seen.lock().unwrap().iter() {
        let action = match sid.as_str() {
            "s-a" if !first_a => {
                first_a = true;
                "FirstA"
            }
            "s-a" => "RetryA",
            "s-b" => "FirstB",
            _ => panic!("unexpected restored tab {sid}"),
        };
        assert!(model.fire(action, &mut state), "{action}: {state:?}");
        if action == "FirstA" {
            assert!(!model.action_enabled("RetryA", &state));
            let buggy = aterm_spec::interp::with_buggy(&model, 1);
            assert!(buggy.action_enabled("RetryA", &state));
        }
    }
}

/// Shorter host steps must not exhaust the old in-flight window after
/// eight fast `wait:resume` reads. Other waits retain the bounded budget,
/// and a typed failure never retries.
#[test]
fn a_restored_in_flight_relaunch_stays_eligible_until_stale() {
    let waiting = Outcome::NotYet("wait:resume".to_string());
    assert!(restored_retry(
        "wait:resume",
        &waiting,
        RESTORED_TRIES,
        Duration::from_secs(relaunch::STALE_S - 1)
    ));
    assert!(!restored_retry(
        "wait:resume",
        &waiting,
        RESTORED_TRIES,
        Duration::from_secs(relaunch::STALE_S)
    ));
    assert!(!restored_retry(
        "wait:shell-prompt",
        &Outcome::NotYet("wait:shell-prompt".to_string()),
        RESTORED_TRIES,
        Duration::ZERO
    ));
    assert!(!restored_retry(
        "failed:no-resume",
        &Outcome::NotYet("failed:no-resume".to_string()),
        1,
        Duration::ZERO
    ));
}

/// RULING 293: an agent the reopened row said resumes and that did not
/// come back is said ONCE, in one row, once every restored tab is tried:
/// here tab 2's shell was gone (`refused:shell-gone`). NEGATIVE CONTROLS
/// in the same pass: tab 1's relaunch landed (`adopted`) and tab 3's agent
/// had no conversation (the reopened row already counted it lost), so
/// neither is in the row.
#[test]
fn a_restored_agent_that_did_not_come_back_is_said_once() {
    let _lane = crate::message_inbox::own_lane_for_test();
    let _ = crate::message_inbox::take_queued();
    let world = Arc::new(World::default());
    let tried: Arc<Mutex<Vec<String>>> = Arc::default();
    let mut h = hooks(&world, parking_body(&world));
    let t = Arc::clone(&tried);
    h.acts.relaunch_restored = Arc::new(move |sid, _, _, _| {
        t.lock().unwrap().push(sid.to_string());
        if sid == "s-a" {
            "adopted"
        } else {
            "refused:shell-gone"
        }
        .to_string()
    });
    let host = HostHandle::start(on(), false, false, h);
    let mut lost = restored("s-c", "in tab 3");
    lost.snap.session = None;
    host.relaunch_restored(vec![
        restored("s-a", "in tab 1"),
        restored("s-b", "in tab 2"),
        lost,
    ]);
    until("all three tried", || tried.lock().unwrap().len() == 3);
    let rows = restored_rows(Duration::from_secs(60));
    assert_eq!(rows.len(), 1, "{rows:?}");
    let row = &rows[0].message;
    assert!(row.title.ends_with("tab 2"), "{}", row.title);
    assert!(
        row.detail
            .iter()
            .all(|l| !l.contains("tab 1") && !l.contains("tab 3")),
        "{:?}",
        row.detail
    );
}

/// DAY SIX, D30: a restored tab's relaunch that was TYPED AND DID NOT
/// TAKE (`failed:no-resume`: the agent started and ended without its
/// conversation) is tried once — another try types the same line into the
/// tab again — and said at once, its reason true (D31) and the remedy in
/// the plain sentence (D32). NEGATIVE CONTROLS: a step not possible yet
/// (`wait:shell-prompt`) is tried again, up to [`RESTORED_TRIES`]; so is
/// another actor on the lock; a landed relaunch is not.
#[test]
fn a_restored_relaunch_typed_that_did_not_take_is_tried_once_and_said_at_once() {
    assert!(!restored_again(
        "failed:no-resume",
        &relaunch::outcome("failed:no-resume")
    ));
    assert!(!restored_again(
        "failed:relaunch:ERR-busy",
        &relaunch::outcome("failed:relaunch:ERR-busy")
    ));
    for again in ["wait:shell-prompt", "wait:resume", "busy:another-sweep"] {
        assert!(restored_again(again, &relaunch::outcome(again)), "{again}");
    }
    assert!(!restored_again("adopted", &relaunch::outcome("adopted")));

    let _lane = crate::message_inbox::own_lane_for_test();
    let _ = crate::message_inbox::take_queued();
    let world = Arc::new(World::default());
    let tried = Arc::new(AtomicUsize::new(0));
    let mut h = hooks(&world, parking_body(&world));
    let t = Arc::clone(&tried);
    h.acts.relaunch_restored = Arc::new(move |_, _, _, _| {
        t.fetch_add(1, Ordering::SeqCst);
        "failed:no-resume".to_string()
    });
    let host = HostHandle::start(on(), false, false, h);
    host.relaunch_restored(vec![restored("s-a", "in tab 1")]);
    let rows = restored_rows(Duration::from_secs(60));
    // SAID WITHOUT A PAUSE — BY ORDER, not by a clock whose bound was the
    // pause itself (1 s, which a loaded machine crossed on the pass). The
    // queue's worker says its row only once its queue is empty
    // (`relaunch_restored_queue`), and a retry is queued, its pause owed,
    // before the queue can empty: a row seen with one try on the counter
    // and nothing owed was said right after that one try, with no retry
    // and so no pause. D30's defect retries the typed line a
    // RESTORED_FIRST_PAUSE later and says the row after the last of
    // RESTORED_TRIES tries — past this minute's hang detector.
    assert_eq!(
        (rows.len(), tried.load(Ordering::SeqCst)),
        (1, 1),
        "said once, after one try with no retry: {rows:?}"
    );
    assert!(
        host.pending_restored().is_empty(),
        "nothing is owed a retry: the worker has exited and nothing types the line again"
    );
    let row = &rows[0].message;
    assert!(row.title.ends_with("tab 1"), "{}", row.title);
    assert!(
        row.detail[0].contains("claude --resume"),
        "the remedy names the command: {:?}",
        row.detail
    );
}

/// A RESTORED AGENT'S RELAUNCH IS TOLD THE TAB IT RAN IN (2026-10-15, the
/// cross-lane review's XREV-LC-1): the queue hands the act the sid of the
/// tab a cold restore's layout names ([`RestoredAgent::was`]), which the
/// relaunch keeps among the conversation's earlier tabs so that tab's loop
/// turns read as the harness's own. NEGATIVE CONTROL in the same queue: an
/// agent naming no other tab is told none.
#[test]
fn a_restored_agents_relaunch_is_told_the_tab_it_ran_in() {
    let _lane = crate::message_inbox::own_lane_for_test();
    let _ = crate::message_inbox::take_queued();
    let world = Arc::new(World::default());
    // Each relaunch's tab and the tab it was told it ran in.
    type Told = Mutex<Vec<(String, Option<String>)>>;
    let told: Arc<Told> = Arc::default();
    let mut h = hooks(&world, parking_body(&world));
    let t = Arc::clone(&told);
    h.acts.relaunch_restored = Arc::new(move |sid, _, _, was| {
        t.lock()
            .unwrap()
            .push((sid.to_string(), was.map(str::to_owned)));
        "refused:shell-gone".to_string()
    });
    let host = HostHandle::start(on(), false, false, h);
    let old = "s-00000000000000000001";
    host.relaunch_restored(vec![
        RestoredAgent {
            was: Some(old.to_string()),
            ..restored("s-cold", "in tab 2")
        },
        restored("s-plain", "in tab 3"),
    ]);
    until("both attempts over", || {
        host.pending_restored().is_empty() && told.lock().unwrap().len() == 2
    });
    let mut told = told.lock().unwrap().clone();
    told.sort();
    assert_eq!(
        told,
        [
            ("s-cold".to_string(), Some(old.to_string())),
            ("s-plain".to_string(), None)
        ]
    );
    // The queue says its row after its last attempt is over: read here,
    // under the lane's guard, or the next test's drain takes it.
    let rows = restored_rows(Duration::from_secs(60));
    assert_eq!(
        rows.iter()
            .map(|row| row.message.title.as_str())
            .collect::<Vec<_>>(),
        ["Couldn't resume Claude in 2 tabs"]
    );
    host.shutdown_and_join();
}

/// A RESTORED AGENT'S EARLIER TAB IS NOTED WHATEVER THE QUEUE DOES (the
/// decision review's RR-LC-3): a held tab's agent is never queued, so no
/// relaunch records the tab it ran in, and the note beside its reopened tab's
/// ledger ([`Acts::earlier_tab`]) is what keeps the old loop's turns the
/// harness's. Noted as the restore hands the agents over, and as it says a
/// held one — here the host's helper alone ([`HostHandle::note_earlier_tab`]:
/// a kept sid notes nothing); the App's path through it, the only one a held
/// tab's note takes, is `app_restore`'s
/// `a_held_tabs_agent_has_its_earlier_tab_noted_as_the_restore_says_it`.
/// NEGATIVE CONTROLS: an agent naming no other tab, and one naming its own
/// (a kept sid), note nothing.
#[test]
fn a_restored_agents_earlier_tab_is_noted_whatever_the_queue_does() {
    let _lane = crate::message_inbox::own_lane_for_test();
    let _ = crate::message_inbox::take_queued();
    let world = Arc::new(World::default());
    type Noted = Mutex<Vec<(String, String)>>;
    let noted: Arc<Noted> = Arc::default();
    let mut h = hooks(&world, parking_body(&world));
    let n = Arc::clone(&noted);
    h.acts.earlier_tab = Arc::new(move |sid, was| {
        n.lock().unwrap().push((sid.to_string(), was.to_string()));
    });
    h.acts.relaunch_restored = Arc::new(|_, _, _, _| "refused:shell-gone".to_string());
    let host = HostHandle::start(on(), false, false, h);
    let (old_held, old_free) = ("s-00000000000000000001", "s-00000000000000000002");
    // The held tab's agent, said by the restore and never queued.
    host.note_earlier_tab("s-held", old_held);
    host.note_earlier_tab("s-kept-held", "s-kept-held");
    host.relaunch_restored(vec![
        RestoredAgent {
            was: Some(old_free.to_string()),
            ..restored("s-free", "in tab 3")
        },
        restored("s-plain", "in tab 4"),
        RestoredAgent {
            was: Some("s-kept".to_string()),
            ..restored("s-kept", "in tab 5")
        },
    ]);
    until("every attempt over", || host.pending_restored().is_empty());
    // The queue says its row after its last attempt is over: read here,
    // under the lane's guard, or the next test's drain takes it. The held
    // tab is not on it.
    let rows = restored_rows(Duration::from_secs(60));
    assert_eq!(
        rows.iter()
            .map(|row| row.message.title.as_str())
            .collect::<Vec<_>>(),
        ["Couldn't resume Claude in 3 tabs"]
    );
    let mut noted = noted.lock().unwrap().clone();
    noted.sort();
    assert_eq!(
        noted,
        [
            ("s-free".to_string(), old_free.to_string()),
            ("s-held".to_string(), old_held.to_string()),
        ]
    );
    host.shutdown_and_join();
}

/// A restored attempt of tab `s-d` tried `tried` times, `landed` as given.
fn landing_attempt(tried: u32, landed: bool) -> RestoredAttempt {
    RestoredAttempt {
        agent: restored("s-d", "in tab 2"),
        order: 0,
        due: Instant::now(),
        pause: RESTORED_FIRST_PAUSE,
        tried,
        resume_wait_since: None,
        acting: false,
        agent_seen: false,
        carried: false,
        landed,
        faults: 0,
        in_flight_only: false,
        revoked: Arc::default(),
    }
}

/// `agent`'s first attempt, `order` in the layout's, as the queue takes it
/// up — put on a queue by hand, no worker started, so nothing steps it or
/// says its row meanwhile.
fn queued_attempt(agent: RestoredAgent, order: usize) -> RestoredAttempt {
    RestoredAttempt {
        agent,
        order,
        due: Instant::now(),
        pause: RESTORED_FIRST_PAUSE,
        tried: 0,
        resume_wait_since: None,
        acting: false,
        agent_seen: false,
        carried: false,
        landed: false,
        faults: 0,
        in_flight_only: false,
        revoked: Arc::default(),
    }
}

/// A RESTORED LANDING'S ADOPTED AGENT THE RECORD SAYS IS GONE IS RELAUNCHED
/// AGAIN, on a first look too (the residual review's R5): the look right
/// after an `adopted` step that reads no agent and finds none named in its
/// tab ended the attempt `landed`, left to the roster — an agent that died
/// in that moment was relaunched by nobody and told to nobody. Decided by
/// the conversation's record ([`LandingLook::Died`]): within the budget the
/// attempt is kept, `landed` off and its next step due on its back-off; past
/// the budget it is over, said missed. NEGATIVE CONTROL: [`LandingLook::Gone`]
/// on a first look, where the record says nothing, is still left to the
/// roster.
#[test]
fn a_restored_landing_the_record_says_died_is_relaunched_again() {
    let before = Instant::now();
    match restored_landing_ends(
        landing_attempt(1, false),
        LandingLook::Died,
        LANDED_LOOK,
        RESTORED_FIRST_PAUSE,
    ) {
        LandingEnd::Keep(a) => {
            assert!(!a.landed, "no agent of its own in the tab");
            assert!(a.due >= before + RESTORED_FIRST_PAUSE, "on its back-off");
            assert!(a.pause > RESTORED_FIRST_PAUSE, "the back-off doubles");
        }
        LandingEnd::Over(_, last, step) => panic!("kept, not over: {last:?} {step}"),
    }
    match restored_landing_ends(
        landing_attempt(RESTORED_TRIES, false),
        LandingLook::Died,
        LANDED_LOOK,
        RESTORED_FIRST_PAUSE,
    ) {
        LandingEnd::Over(_, last, step) => {
            assert_eq!(
                (last, step),
                (Outcome::Cannot(LANDED_GONE.to_string()), LANDED_GONE)
            );
        }
        LandingEnd::Keep(_) => panic!("past the budget: over"),
    }
    // NEGATIVE CONTROL: the record says nothing, a first look.
    match restored_landing_ends(
        landing_attempt(1, false),
        LandingLook::Gone,
        LANDED_LOOK,
        RESTORED_FIRST_PAUSE,
    ) {
        LandingEnd::Over(_, last, step) => {
            assert_eq!((last, step), (Outcome::Relaunched, "landed"))
        }
        LandingEnd::Keep(_) => panic!("left to the roster"),
    }
}

/// THE LANDING'S LOOK ASKS THE RECORD where no read reaches the agent (the
/// residual review's R5): no snapshot read and nothing named in the tab, the
/// adopted process alive by the record is held unread, gone by the record
/// is [`LandingLook::Died`]; the record saying nothing leaves the look as it
/// was ([`LandingLook::Gone`]).
#[test]
fn a_landings_look_asks_the_record_where_no_read_reaches_it() {
    let _lane = crate::message_inbox::own_lane_for_test();
    let world = Arc::new(World::default());
    for (said, want) in [
        (Some(true), LandingLook::Died),
        (Some(false), LandingLook::Unread),
        (None, LandingLook::Gone),
    ] {
        let mut h = hooks(&world, parking_body(&world));
        h.acts.snapshot = Arc::new(|_| None);
        h.still_wanted = Arc::new(|_, _| false);
        h.acts.adopted_gone = Arc::new(move |_, _| said);
        let host = HostHandle::start(on(), false, false, h.clone());
        let agent = restored("s-d", "in tab 2");
        let look = restored_landing_look(
            &host.shared,
            &h,
            &agent.sid,
            false,
            &agent.snap,
            &AtomicBool::new(false),
        );
        assert_eq!(look, want, "{said:?}");
        host.shutdown_and_join();
    }
}

/// A HELD TAB'S END IS JOURNALED AS EVERY OTHER END OF THE QUEUE'S RELAUNCHES
/// IS (the review of ATERM-KI-1015-1 LC-8; `App::say_restored_held`): the
/// relaunch's own line, `relaunch-after-host-ended pid=… tab=… session=…
/// from=… to=… step=…`, its step `ended:held` — never a sentence of its own
/// that no reader of those lines finds.
#[test]
fn a_held_tabs_end_is_journaled_as_the_queues_other_ends_are() {
    let agent = restored("s-held", "in tab 2");
    let line = |version: Option<&str>| {
        restored_held_line(
            agent.snap.pid,
            &agent.sid,
            agent.snap.session.as_deref(),
            version,
        )
    };
    assert_eq!(
        line(None),
        "relaunch-after-host-ended pid=4242 tab=s-held \
         session=0b6f3c1e-8a4d-4b61-9d52-7f1e2c3a4b5c from=- to=- step=ended:held"
    );
    assert!(
        line(Some("2.1.300")).contains(" from=2.1.300 to=- step=ended:held"),
        "{}",
        line(Some("2.1.300"))
    );
    assert!(
        restored_held_line(1, "s-x", None, None).contains(" session=- "),
        "no conversation"
    );
}

